1	/**
2	 * Managed first-month-free promotion — the atomic redemption core.
3	 *
4	 * This mirrors lib/order.ts `claimOrderCoupon`: a conditional INSERT guarded by
5	 * two @@unique constraints (PromoRedemption `@@unique([promoId,userId])` and
6	 * `@@unique([promoId,ipHash])`) that runs INSIDE the order's charge transaction.
7	 * If the insert violates either constraint (this account OR this IP already
8	 * redeemed) it returns `{ claimed: false }` — it never throws for that case — so
9	 * the caller can charge the FULL price and still complete the order.
10	 *
11	 * THE MONEY RULE (owner will review this file personally):
12	 *   - The free-month credit is applied to an order ONLY when `claimed === true`.
13	 *   - If the claim is lost (already redeemed by account/IP) OR the promo is
14	 *     switched off via the `first_month_free_enabled` setting, the customer is
15	 *     charged the FULL price. The order still succeeds — it just isn't free.
16	 *   - The caps are FIXED at 1/account + 1/IP and are enforced ONLY by the two
17	 *     unique constraints. There is no configurable cap to drift out of sync.
18	 *
19	 * WHY A TYPED VIEW instead of `db.promoRedemption` directly: the Prisma client in
20	 * this tree is symlinked from prod and is only regenerated at deploy time, so its
21	 * types do not yet know about the new PromoRedemption model. Rather than sprinkle
22	 * `as any` across four money-critical order flows, every raw-delegate access is
23	 * contained HERE behind `promoDelegate(...)`, and the rest of the codebase calls
24	 * the strongly-typed helpers below. When the client is regenerated the runtime is
25	 * identical; only these casts become redundant.
26	 */
27	
28	import { randomUUID } from "crypto";
29	import { Prisma } from "@prisma/client";
30	import { db } from "./db";
31	
32	/** The single managed promo id. */
33	export const FIRST_MONTH_FREE_PROMO_ID = "first-month-free";
34	
35	/**
36	 * Redemption row lifecycle. A wallet-atomic flow inserts a CONSUMED grant in one
37	 * step; the card/Stripe flow first inserts a RESERVED hold (before the card is
38	 * charged) and later confirms it to CONSUMED. Both states physically occupy the two
39	 * unique slots, so a live hold blocks a second claim exactly like a grant.
40	 */
41	export const PROMO_STATE = { RESERVED: "RESERVED", CONSUMED: "CONSUMED" } as const;
42	export type PromoState = (typeof PROMO_STATE)[keyof typeof PROMO_STATE];
43	
44	/** Products the promo can be granted on (matches PromoRedemption.serviceType). */
45	export type PromoServiceType = "VPS" | "HOSTING" | "EMAIL" | "GAME";
46	
47	/** A minimal, honestly-typed shape of the row we read back. */
48	export type PromoRedemptionRow = {
49	  id: string;
50	  promoId: string;
51	  userId: string;
52	  ipHash: string | null;
53	  serviceType: string;
54	  campaign: string;
55	  orderRef: string | null;
56	  renewed: boolean;
57	  renewedAt: Date | null;
58	  chargedCents: number;
59	  state: string;
60	  reservedUntil: Date | null;
61	  reservationToken: string | null;
62	  createdAt: Date;
63	};
64	
65	/**
66	 * The subset of the PromoRedemption Prisma delegate this module uses, typed by
67	 * hand so the call sites stay type-checked even before the client is regenerated.
68	 */
69	type PromoWhere = {
70	  promoId?: string;
71	  userId?: string;
72	  ipHash?: string;
73	  orderRef?: string;
74	  renewed?: boolean;
75	  state?: string;
76	  reservationToken?: string;
77	  reservedUntil?: { lt: Date };
78	};
79	type PromoDelegate = {
80	  create(args: {
81	    data: {
82	      promoId?: string;
83	      userId: string;
84	      ipHash: string | null;
85	      serviceType: string;
86	      campaign: string;
87	      orderRef?: string | null;
88	      chargedCents: number;
89	      state?: string;
90	      reservedUntil?: Date | null;
91	      reservationToken?: string | null;
92	    };
93	    select?: { id: true };
94	  }): Promise<{ id: string }>;
95	  findUnique(args: {
96	    where: { promoId_userId: { promoId: string; userId: string } };
97	    select?: { id: true };
98	  }): Promise<{ id: string } | null>;
99	  findFirst(args: {
100	    where: PromoWhere;
101	    select?: { id: true };
102	  }): Promise<{ id: string } | null>;
103	  findMany(args?: {
104	    where?: PromoWhere;
105	    orderBy?: { createdAt: "asc" | "desc" };
106	  }): Promise<PromoRedemptionRow[]>;
107	  updateMany(args: {
108	    where: PromoWhere;
109	    data: { renewed?: boolean; renewedAt?: Date; state?: string; reservedUntil?: Date | null };
110	  }): Promise<{ count: number }>;
111	  update(args: {
112	    where: { id: string };
113	    data: { orderRef?: string | null; chargedCents?: number };
114	  }): Promise<{ id: string }>;
115	  deleteMany(args: { where: PromoWhere }): Promise<{ count: number }>;
116	  count(args?: { where?: PromoWhere }): Promise<number>;
117	};
118	
119	/** Anything that carries a `promoRedemption` delegate — the client or a tx client. */
120	type PromoClient = Prisma.TransactionClient | typeof db;
121	
122	/** The one place the stale-client cast lives. */
123	function promoDelegate(client: PromoClient): PromoDelegate {
124	  return (client as unknown as { promoRedemption: PromoDelegate }).promoRedemption;
125	}
126	
127	/** Is the sitewide first-month-free offer switched on? (Owner toggle.) */
128	export async function firstMonthFreeEnabled(): Promise<boolean> {
129	  // Imported lazily so this module stays importable from the worker (no request
130	  // scope) without dragging server-only settings wiring into every consumer.
131	  const { getSettingBool } = await import("./settings");
132	  return getSettingBool("first_month_free_enabled", true);
133	}
134	
135	/**
136	 * Which products the first-month-free promo is granted on. Owner decision
137	 * (2026-08-11): **Shared Web Hosting ONLY**. A free month of a $2.99–$8.99
138	 * hosting plan is a cheap acquisition offer for the first paid ad channel;
139	 * a free month of a $6.49–$32.99 VPS (or a game/email plan) is real exposure.
140	 * VPS / EMAIL / GAME always bill full. To extend the promo to another product
141	 * later, add its PromoServiceType here — every order flow reads this one gate,
142	 * so nothing else changes.
143	 */
144	export const FIRST_MONTH_FREE_SERVICES: PromoServiceType[] = ["HOSTING"];
145	
146	/** Does the first-month-free promo apply to this product? (See above.) */
147	export function firstMonthFreeAppliesTo(service: PromoServiceType): boolean {
148	  return FIRST_MONTH_FREE_SERVICES.includes(service);
149	}
150	
151	/**
152	 * Read-only pre-check: could THIS user / IP still claim the promo? Mirrors
153	 * `orderCouponClaimable` — used before the wallet balance gate so a first-time,
154	 * $0-balance customer can be quoted the free (zero) price and pass the gate,
155	 * while a repeat account/IP is quoted (and gated against) the full price. It is
156	 * advisory only; the authoritative decision is the atomic `claimFirstMonthFree`
157	 * inside the charge tx, which is the sole arbiter of whether money is discounted.
158	 */
159	export async function firstMonthFreeEligible(
160	  userId: string,
161	  ipHash: string | null,
162	): Promise<boolean> {
163	  const d = promoDelegate(db);
164	  const byUser = await d.findUnique({
165	    where: { promoId_userId: { promoId: FIRST_MONTH_FREE_PROMO_ID, userId } },
166	    select: { id: true },
167	  });
168	  if (byUser) return false;
169	  if (ipHash) {
170	    const byIp = await d.findFirst({
171	      where: { promoId: FIRST_MONTH_FREE_PROMO_ID, ipHash },
172	      select: { id: true },
173	    });
174	    if (byIp) return false;
175	  }
176	  return true;
177	}
178	
179	/**
180	 * Delete THIS claimant's own dead holds — RESERVED rows whose `reservedUntil` has
181	 * passed and which were never confirmed (an abandoned/expired card checkout). This
182	 * is the guarantee that an abandoned checkout can NEVER permanently burn a
183	 * customer's one eligibility: the very next claim/reserve attempt sweeps its own
184	 * stale hold before contending, independently of the webhook and the worker sweep.
185	 *
186	 * It is strictly guarded — `state: RESERVED` AND `reservedUntil < now` — so a
187	 * CONSUMED grant or a still-live hold is NEVER touched. Cleaning by ipHash frees
188	 * the shared-IP slot for anyone (a dead hold should block nobody), which is correct.
189	 */
190	async function releaseExpiredReservationsFor(
191	  d: PromoDelegate,
192	  userId: string,
193	  ipHash: string | null,
194	): Promise<void> {
195	  const now = new Date();
196	  await d.deleteMany({
197	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, state: PROMO_STATE.RESERVED, reservedUntil: { lt: now }, userId },
198	  });
199	  if (ipHash) {
200	    await d.deleteMany({
201	      where: { promoId: FIRST_MONTH_FREE_PROMO_ID, state: PROMO_STATE.RESERVED, reservedUntil: { lt: now }, ipHash },
202	    });
203	  }
204	}
205	
206	export type ClaimResult = { claimed: true; id: string } | { claimed: false };
207	
208	/**
209	 * THE ATOMIC CLAIM. Conditional INSERT of a PromoRedemption inside the caller's
210	 * charge transaction. Returns `{ claimed: true, id }` on success, or
211	 * `{ claimed: false }` when the row already exists for this account OR this IP
212	 * (Prisma P2002 on either unique constraint). Any OTHER database error is
213	 * rethrown so it rolls the whole charge tx back — a lost claim is expected and
214	 * cheap; an unexpected failure must not silently grant a free month.
215	 *
216	 * `orderRef` is usually still unknown here (the server/account id is generated
217	 * later in the same tx), so it is filled in afterwards via `setPromoOrderRef`.
218	 */
219	export async function claimFirstMonthFree(
220	  tx: Prisma.TransactionClient,
221	  opts: {
222	    userId: string;
223	    ipHash: string | null;
224	    serviceType: PromoServiceType;
225	    campaign: string;
226	    chargedCents: number;
227	    orderRef?: string | null;
228	  },
229	): Promise<ClaimResult> {
230	  try {
231	    // Self-heal first: a dead hold from THIS customer's own abandoned card checkout
232	    // must not stand between them and the free month on a fresh (wallet) order.
233	    await releaseExpiredReservationsFor(promoDelegate(tx), opts.userId, opts.ipHash);
234	    const row = await promoDelegate(tx).create({
235	      data: {
236	        promoId: FIRST_MONTH_FREE_PROMO_ID,
237	        userId: opts.userId,
238	        ipHash: opts.ipHash,
239	        serviceType: opts.serviceType,
240	        campaign: opts.campaign,
241	        orderRef: opts.orderRef ?? null,
242	        chargedCents: opts.chargedCents,
243	        // A direct grant. RESERVED is only ever produced by reserveFirstMonthFree.
244	        state: PROMO_STATE.CONSUMED,
245	      },
246	      select: { id: true },
247	    });
248	    return { claimed: true, id: row.id };
249	  } catch (e) {
250	    if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === "P2002") {
251	      // Unique violation on (promo,user) or (promo,ipHash): already redeemed.
252	      return { claimed: false };
253	    }
254	    throw e;
255	  }
256	}
257	
258	export type ReserveResult = { reserved: true; token: string } | { reserved: false };
259	
260	/**
261	 * THE CARD/STRIPE HOLD. Insert a RESERVED redemption BEFORE the card is charged, so
262	 * a second concurrent checkout can't also pass eligibility and walk away with a
263	 * second free month. This is the atomic gate for the up-front-settlement path — its
264	 * INSERT contends on the SAME two unique constraints as the grant, so exactly one of
265	 * N racing checkouts holds the slot; the losers get `{ reserved: false }` and the
266	 * caller re-quotes at FULL price (displayed === charged).
267	 *
268	 * Runs on the base client (not a tx): it is a single guarded insert, taken before
269	 * any Stripe session exists. The returned `token` is stamped into the Checkout
270	 * session's metadata and is what `confirmReservation` / `releaseReservation` target.
271	 */
272	export async function reserveFirstMonthFree(opts: {
273	  userId: string;
274	  ipHash: string | null;
275	  serviceType: PromoServiceType;
276	  campaign: string;
277	  chargedCents: number;
278	  /** When this hold may be reaped if never confirmed (session lifetime + grace). */
279	  reservedUntil: Date;
280	}): Promise<ReserveResult> {
281	  const d = promoDelegate(db);
282	  const token = `pmr_${randomUUID()}`;
283	  try {
284	    // Clear this claimant's own dead holds first, so an earlier abandoned checkout
285	    // never blocks a new one — the "no permanently-burned eligibility" guarantee.
286	    await releaseExpiredReservationsFor(d, opts.userId, opts.ipHash);
287	    await d.create({
288	      data: {
289	        promoId: FIRST_MONTH_FREE_PROMO_ID,
290	        userId: opts.userId,
291	        ipHash: opts.ipHash,
292	        serviceType: opts.serviceType,
293	        campaign: opts.campaign,
294	        chargedCents: opts.chargedCents,
295	        state: PROMO_STATE.RESERVED,
296	        reservedUntil: opts.reservedUntil,
297	        reservationToken: token,
298	      },
299	      select: { id: true },
300	    });
301	    return { reserved: true, token };
302	  } catch (e) {
303	    if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === "P2002") {
304	      // Unique violation on (promo,user) or (promo,ipHash): already held or redeemed.
305	      return { reserved: false };
306	    }
307	    throw e;
308	  }
309	}
310	
311	/**
312	 * Confirm a hold at fulfilment: flip its RESERVED row to CONSUMED, inside the order's
313	 * charge tx so the grant commits with the money. The `state: RESERVED` guard makes it
314	 * idempotent (a replayed fulfil, or a race with the sweep, matches zero rows) and
315	 * guarantees we never "confirm" a hold that was already released. Returns the row id
316	 * (to anchor `orderRef`), or null when there is no live hold to confirm.
317	 */
318	export async function confirmReservation(
319	  tx: Prisma.TransactionClient,
320	  token: string,
321	): Promise<{ id: string } | null> {
322	  const d = promoDelegate(tx);
323	  const row = await d.findFirst({
324	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, reservationToken: token },
325	    select: { id: true },
326	  });
327	  if (!row) return null;
328	  const res = await d.updateMany({
329	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, reservationToken: token, state: PROMO_STATE.RESERVED },
330	    data: { state: PROMO_STATE.CONSUMED, reservedUntil: null },
331	  });
332	  // count 0 => it was already consumed (a replay) or released; either way there is
333	  // nothing to newly grant on this call.
334	  return res.count === 1 ? { id: row.id } : null;
335	}
336	
337	/**
338	 * Release a hold (delete the RESERVED row) so an abandoned/expired checkout returns
339	 * the customer's one eligibility. Guarded to `state: RESERVED` so it can NEVER delete
340	 * a CONSUMED grant — a paid, confirmed free month is never revoked by a late expiry
341	 * event. Called from the `checkout.session.expired` webhook.
342	 */
343	export async function releaseReservation(token: string): Promise<void> {
344	  await promoDelegate(db).deleteMany({
345	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, reservationToken: token, state: PROMO_STATE.RESERVED },
346	  });
347	}
348	
349	/**
350	 * Backstop sweep: delete every RESERVED hold whose `reservedUntil` has passed. Runs
351	 * on the worker so a dead hold is reclaimed even if the `checkout.session.expired`
352	 * webhook is not configured or was missed. Returns how many were reaped. Guarded to
353	 * RESERVED, so a CONSUMED grant is untouchable here.
354	 */
355	export async function sweepExpiredReservations(now = new Date()): Promise<number> {
356	  const res = await promoDelegate(db).deleteMany({
357	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, state: PROMO_STATE.RESERVED, reservedUntil: { lt: now } },
358	  });
359	  return res.count;
360	}
361	
362	/**
363	 * Backfill the created server/account/subscription id (and the final charged
364	 * amount) onto a redemption we just claimed, in the same tx. Kept off the claim
365	 * itself because the resource id is minted after the claim within the tx.
366	 */
367	export async function setPromoOrderRef(
368	  tx: Prisma.TransactionClient,
369	  redemptionId: string,
370	  orderRef: string,
371	  chargedCents: number,
372	): Promise<void> {
373	  await promoDelegate(tx).update({
374	    where: { id: redemptionId },
375	    data: { orderRef, chargedCents },
376	  });
377	}
378	
379	/**
380	 * Mark the promo redemption anchored to `orderRef` as RENEWED, the first time
381	 * that service bills its SECOND term. Idempotent: the `renewed: false` guard
382	 * means a repeated/racing renewal sweep matches zero rows and does nothing.
383	 * Called inside the renewal charge tx so it commits with the money.
384	 */
385	export async function markPromoRenewed(
386	  tx: Prisma.TransactionClient,
387	  orderRef: string,
388	): Promise<void> {
389	  await promoDelegate(tx).updateMany({
390	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, orderRef, renewed: false },
391	    data: { renewed: true, renewedAt: new Date() },
392	  });
393	}
394	
395	/** One-month credit for a flat-priced term (used by the game flow). */
396	export function firstMonthCreditCents(termPriceCents: number, termMonths: number): number {
397	  if (termMonths <= 1) return termPriceCents; // whole (single-month) term is free
398	  const oneMonth = Math.round(termPriceCents / termMonths);
399	  return Math.min(termPriceCents, oneMonth);
400	}
401	
402	// ---------------------------------------------------------------------------
403	// Campaign tag (from the /go/<slug>?c=<campaign> cookie)
404	// ---------------------------------------------------------------------------
405	
406	/** The cookie the /go link sets and the order flows read for attribution. */
407	export const PROMO_CAMPAIGN_COOKIE = "nx_promo_campaign";
408	
409	/** Keep campaign tags to a safe, bounded alnum-dash slug (≤40). */
410	export function sanitizeCampaign(raw: string | null | undefined): string {
411	  return String(raw ?? "")
412	    .replace(/[^a-zA-Z0-9-]/g, "")
413	    .slice(0, 40);
414	}
415	
416	/**
417	 * Read + sanitize the campaign tag from an already-resolved cookie jar. Takes the
418	 * jar (not `cookies()`) so this module never imports `next/headers` — that keeps
419	 * it importable from the worker, which has no request scope.
420	 */
421	export function promoCampaignFromCookie(jar: {
422	  get(name: string): { value: string } | undefined;
423	}): string {
424	  return sanitizeCampaign(jar.get(PROMO_CAMPAIGN_COOKIE)?.value);
425	}
426	
427	// ---------------------------------------------------------------------------
428	// Admin stats
429	// ---------------------------------------------------------------------------
430	
431	export type PromoCampaignStat = {
432	  campaign: string;
433	  total: number;
434	  renewed: number;
435	};
436	
437	export type PromoStats = {
438	  total: number;
439	  renewed: number;
440	  /** renewed / total, 0..1. */
441	  conversion: number;
442	  byCampaign: PromoCampaignStat[];
443	  /** Approximate recovered revenue (one renewal term at list price), in cents. */
444	  revenueRecoveredCents: number;
445	  /** True when revenueRecovered had to fall back to an approximation. */
446	  revenueApproximate: boolean;
447	};
448	
449	/**
450	 * Aggregate redemption + conversion stats for the admin Promotions page.
451	 *
452	 * Revenue recovered is APPROXIMATE: for each renewed redemption we price ONE
453	 * renewal term at the underlying plan's current list price (VPS/hosting use the
454	 * plan monthly price; email/game use their stored term price). It is a lower/near
455	 * estimate — it ignores add-ons and multi-term VPS — hence `revenueApproximate`.
456	 */
457	export async function promoStats(): Promise<PromoStats> {
458	  // CONSUMED only — a RESERVED hold is a pending card checkout, not a granted
459	  // redemption, and counting it would inflate the total until it settled or expired.
460	  const rows = await promoDelegate(db).findMany({
461	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, state: PROMO_STATE.CONSUMED },
462	    orderBy: { createdAt: "desc" },
463	  });
464	
465	  const total = rows.length;
466	  const renewedRows = rows.filter((r) => r.renewed);
467	  const renewed = renewedRows.length;
468	
469	  const byCampaignMap = new Map<string, PromoCampaignStat>();
470	  for (const r of rows) {
471	    const key = r.campaign || "(organic)";
472	    const stat = byCampaignMap.get(key) ?? { campaign: key, total: 0, renewed: 0 };
473	    stat.total += 1;
474	    if (r.renewed) stat.renewed += 1;
475	    byCampaignMap.set(key, stat);
476	  }
477	  const byCampaign = [...byCampaignMap.values()].sort((a, b) => b.total - a.total);
478	
479	  // Approximate recovered revenue: one renewal term at list price per renewed row.
480	  let revenueRecoveredCents = 0;
481	  let revenueApproximate = false;
482	  const refs = (type: PromoServiceType) =>
483	    renewedRows.filter((r) => r.serviceType === type && r.orderRef).map((r) => r.orderRef as string);
484	
485	  const vpsRefs = refs("VPS");
486	  const gameRefs = refs("GAME");
487	  const serverRefs = [...vpsRefs, ...gameRefs];
488	  if (serverRefs.length) {
489	    const servers = await db.server.findMany({
490	      where: { id: { in: serverRefs } },
491	      select: { id: true, plan: { select: { priceCents: true } }, gamePlan: { select: { priceCents: true } } },
492	    });
493	    for (const s of servers) {
494	      revenueRecoveredCents += s.gamePlan?.priceCents ?? s.plan?.priceCents ?? 0;
495	    }
496	    revenueApproximate = true;
497	  }
498	
499	  const hostRefs = refs("HOSTING");
500	  if (hostRefs.length) {
501	    const accounts = await db.hostingAccount.findMany({
502	      where: { id: { in: hostRefs } },
503	      select: { plan: { select: { priceCents: true } } },
504	    });
505	    for (const a of accounts) revenueRecoveredCents += a.plan?.priceCents ?? 0;
506	    revenueApproximate = true;
507	  }
508	
509	  const emailRefs = refs("EMAIL");
510	  if (emailRefs.length) {
511	    const subs = await db.emailSubscription.findMany({
512	      where: { id: { in: emailRefs } },
513	      select: { emailPlan: { select: { priceCents: true } } },
514	    });
515	    for (const s of subs) revenueRecoveredCents += s.emailPlan?.priceCents ?? 0;
516	    revenueApproximate = true;
517	  }
518	
519	  return {
520	    total,
521	    renewed,
522	    conversion: total > 0 ? renewed / total : 0,
523	    byCampaign,
524	    revenueRecoveredCents,
525	    revenueApproximate,
526	  };
527	}
