1	/**
2	 * Coupons applied at CHECKOUT of a service (not fungible wallet credit).
3	 *
4	 * This is what makes "one free month on the Starter VPS" mean exactly that:
5	 *  - `serviceKind` + `planSlug` lock the coupon to a product family and/or a
6	 *    single plan, so it cannot be spent on a bigger plan or a different service;
7	 *  - `maxTermMonths` caps how many months of the term it may discount, so a
8	 *    percentage/free coupon cannot be stretched over a 12-month order to hand
9	 *    someone a year for free.
10	 *
11	 * Pure and framework-free so the money maths is unit-tested. The atomic
12	 * redemption claim (count + per-user + per-IP guards) lives in lib/order.ts.
13	 */
14	
15	export type CouponServiceKind = "ANY" | "VPS" | "GAME";
16	export type CouponKind = "PERCENT" | "FIXED_CENTS" | "CREDIT_CENTS";
17	
18	/** The coupon fields the order maths needs. */
19	export type OrderCoupon = {
20	  kind: CouponKind;
21	  value: number;
22	  serviceKind: CouponServiceKind;
23	  planSlug: string | null;
24	  maxTermMonths: number | null;
25	  active: boolean;
26	  expiresAt: Date | null;
27	  maxRedemptions: number | null;
28	  timesRedeemed: number;
29	  minAmountCents: number | null;
30	};
31	
32	export type OrderContext = {
33	  /** "VPS" or "GAME" — what the customer is buying. */
34	  serviceKind: "VPS" | "GAME";
35	  /** The plan's slug, matched against `coupon.planSlug`. */
36	  planSlug: string;
37	  /** The plan's REGULAR monthly price (before term/seasonal discounts), cents. */
38	  planMonthlyCents: number;
39	  /** The term the customer chose, in months. */
40	  termMonths: number;
41	  /** What the plan portion of the order actually costs (first-term, cents). */
42	  planChargeCents: number;
