116	/**
117	 * A stable, non-reversible hash of a claimant IP, for the once-per-person guard.
118	 * We store the hash, never the raw IP — the check only needs equality, and a
119	 * plaintext IP log of everyone who claimed a promo is a liability we don't want.
120	 * `salt` comes from the app secret so hashes aren't portable across deployments.
121	 */
122	export function hashIp(ip: string, salt: string): string {
123	  const clean = String(ip ?? "").trim();
124	  if (!clean) return "";
125	  // Lazy require so this module stays importable in any context; crypto is builtin.
126	  const { createHash } = require("node:crypto") as typeof import("node:crypto");
127	  return createHash("sha256").update(`${salt}:${clean}`).digest("hex");
128	}
