130	/** Human summary of a coupon's scope for the admin list / customer preview. */
131	export function describeCouponScope(coupon: Pick<OrderCoupon, "serviceKind" | "planSlug" | "maxTermMonths">): string {
132	  const parts: string[] = [];
133	  if (coupon.planSlug) parts.push(`${coupon.planSlug} plan only`);
134	  else if (coupon.serviceKind !== "ANY") parts.push(`${coupon.serviceKind} only`);
135	  if (coupon.maxTermMonths) parts.push(`max ${coupon.maxTermMonths} month${coupon.maxTermMonths === 1 ? "" : "s"}`);
136	  return parts.join(" · ") || "any service";
137	}
