135	/**
136	 * Parse a sold price back off Stripe metadata. Returns null unless EVERY field is
137	 * well-formed: a half-parsed price would be worse than no price at all, because
138	 * the caller's fallback (re-quote) is at least internally consistent.
139	 */
140	export function parseOrderPrice(raw: unknown): OrderPrice | null {
141	  let obj: unknown = raw;
142	  if (typeof raw === "string") {
143	    try {
144	      obj = JSON.parse(raw);
145	    } catch {
146	      return null;
147	    }
148	  }
149	  if (!obj || typeof obj !== "object") return null;
150	  const { chargeCents, promoPercent, promoName } = obj as Record<string, unknown>;
151	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
152	  if (typeof promoPercent !== "number" || !Number.isInteger(promoPercent)) return null;
153	  if (promoPercent < 0 || promoPercent > 100) return null;
154	  return { chargeCents, promoPercent, promoName: typeof promoName === "string" ? promoName : "" };
155	}
