186	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
187	async function scheduleNode(planRamMB: number) {
188	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
189	  if (nodes.length === 0) return null;
190	  const loads = await Promise.all(
191	    nodes.map(async (n) => {
192	      const agg = await db.server.findMany({
193	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
194	        select: { plan: { select: { ramMB: true } } },
195	      });
196	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
197	      return { node: n, free: n.capacityRamMB - used };
198	    }),
199	  );
200	  loads.sort((a, b) => b.free - a.free);
201	  return loads[0].node;
202	}
