204	/** Validate + price an order without placing it. Throws OrderError on any problem. */
205	export async function orderQuote(intent: OrderIntent, opts?: { suppressPromo?: boolean }) {
206	  const parsed = orderSchema.safeParse(intent);
207	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
208	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
209	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
210	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
211	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
212	    throw new OrderError(
213	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
214	    );
215	  }
216	  const term = vpsTerm(Number(intent.termMonths ?? 1));
217	  // The admin-configured ANNUAL discount, resolved ONCE here and passed to
218	  // `vpsTermPriceCents` so the annual term is charged at the same rate the deploy
219	  // wizard displayed and every renewal will bill. Ignored for non-annual terms.
220	  const annualPct = await annualDiscountPct();
221	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
222	
223	  // Extra root disk, priced per GB/month and multiplied over the term exactly
224	  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
225	  // promo — the customer pays the same $/GB whichever term they pick, and renews
226	  // at the same rate). Growth is one-way: this is permanent for the server.
227	  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
228	  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
229	  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
230	  const extraDiskCents = extraDiskMonthlyCents * term.months;
231	  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
232	    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
233	  }
234	
235	  // Paid backup RETENTION tier, priced per month and multiplied over the term
236	  // exactly like the extra-disk add-on (NOT promo-discounted — the customer pays
237	  // the same $/mo whichever term or promo, and renews at the same rate through
238	  // renewalCharge). Only PLUS is paid; FREE (the included tier) is $0.
239	  const backupTier = normalizeBackupTier(intent.backupTier);
240	  const backupMonthlyCents =
241	    backupTier === "FREE" ? 0 : backupTierMonthlyCents(backupTier, await backupPlusMonthlyCents());
242	  const backupCents = backupMonthlyCents * term.months;
243	
244	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
245	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
246	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
247	  // real renewal price and this discounted value is the real first-term price.
248	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
249	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
250	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months, annualPct);
251	  const promo = currentPromo(new Date());
252	  // The promo is now MANAGED: the owner can switch it off, and every claim is
253	  // capped 1/account + 1/IP (lib/promo-redemption.ts). When the toggle is off the
254	  // quote shows — and placeOrder charges — the full price, so display === charged
255	  // on the disabled path. When it is on, the quote shows the first-month-free
256	  // price and the atomic claim in placeOrder's tx is the final arbiter of whether
257	  // the credit is actually granted (a lost race there is charged full).
258	  // `suppressPromo` prices this quote at FULL price even when the promo is on —
259	  // the card path uses it to re-quote for a customer who has already redeemed
260	  // (per-account/IP), so their Stripe leg and stamped total are full, not free.
261	  // The first-month-free promo is scoped to Shared Web Hosting only — VPS always
262	  // bills full. `firstMonthFreeAppliesTo("VPS")` is false, so promoEnabled is
263	  // false here and planFirstTermCents falls through to the regular term total.
264	  const promoEnabled =
265	    firstMonthFreeAppliesTo("VPS") && !opts?.suppressPromo && (await firstMonthFreeEnabled());
266	  // First-month-free must credit exactly ONE MONTH — not zero a multi-month term.
267	  // A naive promoPriceCents(termTotal) at 100% off would give a 36-month term 3
268	  // YEARS free. So we subtract one month of the plan's rate from the term total.
269	  // For a 1-month term this lands at $0 (genuinely first month free); for a 12/24/
270	  // 36-month term the customer pays the term minus one month. Renewals bill the
271	  // full vpsTermPriceCents unchanged (worker/billing.ts) — displayed === charged.
272	  const planFirstTermCents =
273	    promoEnabled && promo.firstMonthFree
274	      ? Math.max(0, regularPlanCents - plan.priceCents)
275	      : regularPlanCents;
276	  // The one-month credit this order gets IF the atomic claim succeeds. 0 when the
277	  // promo is off. placeOrder adds it back to charge full when the claim is lost.
278	  const promoCreditCents = regularPlanCents - planFirstTermCents;
279	
280	  // Optional checkout coupon: a service-locked, term-capped discount on the PLAN
281	  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
282	  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
283	  // so the deploy preview can show it; the redemption itself (count + per-user +
284	  // per-IP guards) is claimed atomically in placeOrder.
285	  let couponId: string | null = null;
286	  let couponDiscountCents = 0;
287	  let couponLabel = "";
288	  let couponError = "";
289	  let couponMaxRedemptions: number | null = null;
290	  let couponFirstTimeOnly = false;
291	  const code = (intent.couponCode ?? "").trim().toUpperCase();
292	  if (code) {
293	    if (!(await getSettingBool("coupons_enabled", true))) {
294	      couponError = "Promo codes are currently disabled.";
295	    } else {
296	      const coupon = await db.coupon.findUnique({ where: { code } });
297	      if (!coupon) {
298	        couponError = "That code isn’t valid.";
299	      } else {
300	        const verdict = couponOrderDiscountCents(
301	          {
302	            kind: coupon.kind,
303	            value: coupon.value,
304	            serviceKind: coupon.serviceKind,
305	            planSlug: coupon.planSlug,
306	            maxTermMonths: coupon.maxTermMonths,
307	            active: coupon.active,
308	            expiresAt: coupon.expiresAt,
309	            maxRedemptions: coupon.maxRedemptions,
310	            timesRedeemed: coupon.timesRedeemed,
311	            minAmountCents: coupon.minAmountCents,
312	          },
313	          {
314	            serviceKind: "VPS",
315	            planSlug: plan.slug,
316	            planMonthlyCents: plan.priceCents,
317	            termMonths: term.months,
318	            planChargeCents: planFirstTermCents,
319	          },
320	          new Date(),
321	        );
322	        if (verdict.ok) {
323	          couponId = coupon.id;
324	          couponDiscountCents = verdict.discountCents;
325	          couponLabel = verdict.label;
326	          couponMaxRedemptions = coupon.maxRedemptions;
327	          couponFirstTimeOnly = coupon.firstTimeOnly;
328	        } else {
329	          couponError = verdict.error;
330	        }
331	      }
332	    }
333	  }
334	
335	  const chargeCents = planFirstTermCents - couponDiscountCents + ipCents + extraDiskCents + backupCents;
336	  return {
337	    plan,
338	    os,
339	    term,
340	    chargeCents,
341	    promo,
342	    promoCreditCents,
343	    regularPlanCents,
344	    extraDiskGB,
345	    extraDiskMonthlyCents,
346	    extraDiskCents,
347	    backupTier,
348	    backupMonthlyCents,
349	    backupCents,
350	    couponId,
351	    couponDiscountCents,
352	    couponLabel,
353	    couponError,
354	    couponMaxRedemptions,
355	    couponFirstTimeOnly,
356	  };
357	}
