418	/**
419	 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
420	 *
421	 * The card leg discounts `cardCents` up front and only settles the redemption
422	 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
423	 * paid provision is never stranded. Without this pre-check, a customer who has
424	 * already used a one-per-person code (or isn't first-time) still gets the
425	 * discounted card charge and the swallow hides it. So before we send them to
426	 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
427	 * plain reads; if any fails the caller re-quotes at full price. This is advisory
428	 * (a race could still lose the atomic claim at settle time — that path stays
429	 * swallowed by design), but it closes the everyday bypass.
430	 */
431	export async function orderCouponClaimable(opts: {
432	  couponId: string;
433	  firstTimeOnly: boolean;
434	  maxRedemptions: number | null;
435	  userId: string;
436	  ipHash: string | null;
437	}): Promise<{ ok: true } | { ok: false; error: string }> {
438	  if (opts.firstTimeOnly) {
439	    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
440	    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
441	  }
442	  const byUser = await db.couponRedemption.findUnique({
443	    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
444	  });
445	  if (byUser) return { ok: false, error: "You’ve already used this code." };
446	  if (opts.ipHash) {
447	    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
448	    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
449	  }
450	  if (opts.maxRedemptions !== null) {
451	    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
452	    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
453	  }
454	  return { ok: true };
455	}
