255	/**
256	 * WHAT a paid Checkout session was for — the ONE decision that routes fulfilment.
257	 *
258	 * REAL DEFECT this shape exists to remove (found 2026-07-27 audit). Fulfilment used
259	 * to ask three separate `getCheckout*Intent` helpers, each of which did its OWN
260	 * `sessions.retrieve` inside a `try` that returned `null` on ANY failure. So a
261	 * transient Stripe error — a 5xx, a rate limit, a dropped socket — turned "I could
262	 * not read this session" into "this session has no purchase metadata", and
263	 * `fulfilCheckoutSession` fell through to its plain wallet-top-up branch reporting
264	 * `fulfilled: true`. Card charged, no server, no `FulfilledSession` row, no
265	 * notification, and the webhook returns 200 so Stripe never retries. Exactly the
266	 * class of invisible failure that file was written to end, one layer up.
267	 *
268	 * `unreadable` and `unpaid` are therefore first-class answers, NOT absences. The
269	 * session is retrieved exactly once (`getCheckoutPurpose`, which THROWS rather than
270	 * returning a lie) and classified by a pure function over its metadata.
271	 */
272	export type CheckoutPurpose =
273	  | {
274	      kind: "order";
275	      userId: string;
276	      intent: OrderIntent;
277	      sold: OrderPrice | null;
278	      campaign: string;
279	      /** The first-month-free hold to confirm at fulfilment; null for a full-price order. */
280	      promoReservationToken: string | null;
281	    }
282	  | { kind: "resize"; userId: string; serverId: string; planId: string; chargeCents: number }
283	  | { kind: "diskExpand"; userId: string; serverId: string; addGB: number; chargeCents: number }
284	  /** No purchase metadata: a wallet top-up the customer bought for its own sake. */
285	  | { kind: "topup"; userId: string | null }
286	  /** Not paid (or paid to nobody) — nothing to fulfil and nothing to claim. */
287	  | { kind: "unpaid" }
288	  /** Purchase metadata IS present but cannot be trusted. Never treat as a top-up. */
289	  | { kind: "unreadable"; userId: string | null; detail: string };
