/**
 * Checkout-coupon RESERVATION core — the fix for the concurrent-card-checkout cap
 * bypass (security finding, MED/HIGH).
 *
 * This MIRRORS lib/promo-redemption.ts exactly, adapted for CouponRedemption:
 *   - reserve BEFORE the card is charged (atomic conditional insert + conditional
 *     Coupon.timesRedeemed increment) so a second concurrent checkout can't also
 *     pass eligibility and settle a second discounted charge;
 *   - confirm at fulfilment (RESERVED -> CONSUMED, guarded, idempotent);
 *   - release on `checkout.session.expired` / a failed session-open / the worker
 *     sweep, so an ABANDONED checkout never permanently burns a redemption slot.
 *
 * THE PER-PERSON / GLOBAL CAP (before this): lib/order.ts `orderCouponClaimable`
 * checked eligibility with advisory READS before opening Stripe, and `claimOrderCoupon`
 * ran the atomic claim only at fulfilment — where, on the card path, a failed claim was
 * SWALLOWED so a paid provision wasn't stranded. So N concurrent card checkouts all
 * passed the read, all paid the discounted price, only ONE redemption recorded while ALL
 * N provisioned, defeating one-per-user/IP + global `maxRedemptions`. A RESERVED hold
 * closes that: it occupies the two @@unique slots AND has already incremented the global
 * counter, so exactly one of N racing checkouts holds the slot; the losers re-quote at
 * FULL price (coupon dropped) so displayed === charged for every one of them.
 *
 * TWO differences from the promo mirror, both because a coupon carries a GLOBAL cap:
 *   1. The reserve/release must move `Coupon.timesRedeemed` (reserve +1, release -1),
 *      not just the per-person unique rows — the promo has no such counter.
 *   2. The reserve is keyed by an ARBITRARY couponId, not the single fixed promo id.
 *
 * WHY A TYPED VIEW (`couponRedemptionDelegate`): identical reasoning to
 * promo-redemption.ts — the Prisma client in this tree is symlinked from prod and only
 * regenerated at deploy time, so its types do not yet know CouponRedemption's new
 * `state` / `reservedUntil` / `reservationToken` columns. The stale-client cast is
 * contained HERE, behind one delegate, so no `as any` leaks into the money flows.
 */

import { randomUUID } from "crypto";
import { Prisma } from "@prisma/client";
import { db } from "./db";

/** Redemption row lifecycle. Same two states as PromoRedemption. */
export const COUPON_STATE = { RESERVED: "RESERVED", CONSUMED: "CONSUMED" } as const;
export type CouponRedemptionState = (typeof COUPON_STATE)[keyof typeof COUPON_STATE];

/** The subset of the CouponRedemption delegate this module uses, hand-typed so call
 * sites stay type-checked before the client is regenerated. */
type CouponRedemptionWhere = {
  couponId?: string;
  userId?: string;
  ipHash?: string;
  state?: string;
  reservationToken?: string;
  reservedUntil?: { lt: Date };
};
type CouponRedemptionDelegate = {
  create(args: {
    data: {
      couponId: string;
      userId: string;
      ipHash: string | null;
      amountCents: number;
      context?: string;
      state?: string;
      reservedUntil?: Date | null;
      reservationToken?: string | null;
    };
    select?: { id: true };
  }): Promise<{ id: string }>;
  findFirst(args: {
    where: CouponRedemptionWhere;
    select?: { id: true; couponId?: true };
  }): Promise<{ id: string; couponId?: string } | null>;
  findMany(args: {
    where: CouponRedemptionWhere;
    select?: { id: true; couponId: true };
  }): Promise<{ id: string; couponId: string }[]>;
  updateMany(args: {
    where: CouponRedemptionWhere;
    data: { state?: string; reservedUntil?: Date | null };
  }): Promise<{ count: number }>;
  deleteMany(args: { where: CouponRedemptionWhere }): Promise<{ count: number }>;
};

/** Anything that carries a `couponRedemption` delegate — the client or a tx client. */
type CouponClient = Prisma.TransactionClient | typeof db;

/** The one place the stale-client cast lives. */
function couponRedemptionDelegate(client: CouponClient): CouponRedemptionDelegate {
  return (client as unknown as { couponRedemption: CouponRedemptionDelegate }).couponRedemption;
}

/**
 * Delete THIS claimant's own dead holds for THIS coupon — RESERVED rows whose
 * `reservedUntil` has passed and which were never confirmed (an abandoned/expired card
 * checkout) — and return each freed slot to the global counter. This is the guarantee
 * that an abandoned checkout can NEVER permanently burn a redemption: the very next
 * reserve attempt sweeps its own stale hold (and gives the global slot back) before
 * contending, independently of the webhook and the worker sweep.
 *
 * Strictly guarded — `state: RESERVED` AND `reservedUntil < now` — so a CONSUMED grant
 * or a still-live hold is NEVER touched. Runs inside the caller's tx. Decrements
 * `Coupon.timesRedeemed` by exactly the number of dead holds reaped, so the global cap
 * accounting stays exact.
 */
async function releaseExpiredCouponReservationsFor(
  tx: Prisma.TransactionClient,
  couponId: string,
  userId: string,
  ipHash: string | null,
): Promise<void> {
  const now = new Date();
  const d = couponRedemptionDelegate(tx);
  // Reap this claimant's own dead holds (by user, and by IP if present). Sum the freed
  // slots and hand them back to the global counter in one guarded update.
  let freed = 0;
  const byUser = await d.deleteMany({
    where: { couponId, state: COUPON_STATE.RESERVED, reservedUntil: { lt: now }, userId },
  });
  freed += byUser.count;
  if (ipHash) {
    const byIp = await d.deleteMany({
      where: { couponId, state: COUPON_STATE.RESERVED, reservedUntil: { lt: now }, ipHash },
    });
    freed += byIp.count;
  }
  if (freed > 0) {
    // Never let a self-heal drive the counter below zero (defensive against a manual
    // row edit); the conditional keeps the decrement honest.
    await tx.coupon.updateMany({
      where: { id: couponId, timesRedeemed: { gte: freed } },
      data: { timesRedeemed: { decrement: freed } },
    });
  }
}

export type CouponReserveResult =
  | { reserved: true; token: string }
  | { reserved: false; error: string };

/**
 * THE CARD/STRIPE HOLD. Taken BEFORE the card is charged. In ONE transaction it runs the
 * exact guards `claimOrderCoupon` runs — first-time-only, the atomic conditional
 * `timesRedeemed` increment (the global cap), and the two @@unique inserts
 * (one-per-account + one-per-IP) — but writes a RESERVED row (with a token +
 * `reservedUntil`) instead of a CONSUMED grant. Exactly one of N racing checkouts wins
 * each slot; the losers get `{ reserved: false }` and the caller re-quotes at FULL price
 * with the coupon dropped, so its stamped total, card leg and settlement all agree.
 *
 * The returned `token` is stamped into the Checkout session's metadata and is what
 * `confirmCouponReservation` / `releaseCouponReservation` target.
 */
export async function reserveOrderCoupon(opts: {
  couponId: string;
  maxRedemptions: number | null;
  firstTimeOnly: boolean;
  userId: string;
  ipHash: string | null;
  amountCents: number;
  /** When this hold may be reaped if never confirmed (session lifetime + grace). */
  reservedUntil: Date;
}): Promise<CouponReserveResult> {
  const token = `cpr_${randomUUID()}`;
  try {
    await db.$transaction(async (tx) => {
      // Self-heal first: a dead hold from THIS customer's own abandoned card checkout
      // (and its held global slot) must not stand between them and a fresh reserve.
      await releaseExpiredCouponReservationsFor(tx, opts.couponId, opts.userId, opts.ipHash);

      if (opts.firstTimeOnly) {
        const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
        if (prior > 0) throw new CouponReserveError("This code is for first-time customers only.");
      }
      // Atomic conditional increment — the global cap. Holds the slot for the duration
      // of the checkout; released back if the checkout is abandoned.
      const claim = await tx.coupon.updateMany({
        where:
          opts.maxRedemptions === null
            ? { id: opts.couponId, active: true }
            : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
        data: { timesRedeemed: { increment: 1 } },
      });
      if (claim.count !== 1) throw new CouponReserveError("That code has just been fully claimed.");
      // Conditional INSERT of the RESERVED hold — contends on (coupon,user)/(coupon,ipHash).
      // A P2002 here means this account/IP already holds or redeemed it; it throws and
      // rolls back the increment above with it, so the global slot is NOT consumed on a
      // per-person collision.
      await couponRedemptionDelegate(tx).create({
        data: {
          couponId: opts.couponId,
          userId: opts.userId,
          ipHash: opts.ipHash,
          amountCents: opts.amountCents,
          context: "order",
          state: COUPON_STATE.RESERVED,
          reservedUntil: opts.reservedUntil,
          reservationToken: token,
        },
        select: { id: true },
      });
    });
    return { reserved: true, token };
  } catch (e) {
    if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === "P2002") {
      return { reserved: false, error: "You’ve already used this code." };
    }
    if (e instanceof CouponReserveError) return { reserved: false, error: e.message };
    throw e;
  }
}

/** Internal signal for a guard failure inside the reserve tx (rolls it back). */
class CouponReserveError extends Error {}

/**
 * Confirm a hold at fulfilment: flip its RESERVED row to CONSUMED. The `state: RESERVED`
 * guard makes it idempotent (a replayed fulfil, or a race with the sweep, matches zero
 * rows) and guarantees we never "confirm" a hold that was already released. The global
 * `timesRedeemed` counter is left AS-IS — the reserve already incremented it, and a
 * confirmed redemption keeps that slot. Returns the row id, or null when there is no
 * live hold to confirm.
 *
 * Runs on the base client in its own tiny tx (the coupon claim has always settled
 * outside the order's charge tx — see lib/order.ts — unlike the promo, which confirms
 * inside it). The card has already paid the discounted price, so this is a bookkeeping
 * flip, not a charge.
 */
export async function confirmCouponReservation(token: string): Promise<{ id: string } | null> {
  return db.$transaction(async (tx) => {
    const d = couponRedemptionDelegate(tx);
