// Settle the coupon redemption. A free admin grant never consumes a customer coupon.
// The two paths differ, and that difference is the fix for the concurrent-card-checkout
// cap bypass:
//   WALLET path (no `sold`): claim ATOMICALLY before the order tx, so the order fails
//     cleanly (no money moved) if the last slot just went — unchanged behaviour.
//   CARD path (`sold` present): the coupon was RESERVED (atomic increment + RESERVED
//     insert) BEFORE the card was charged; its hold token rides in
//     `opts.couponReservationToken`. CONFIRM that hold (flip RESERVED->CONSUMED) rather
//     than run a fresh, swallowed claim that let N concurrent checkouts each pay the
//     discount while only one redemption recorded.
if (!freeRequested && quote.couponId && quote.couponDiscountCents > 0) {
  if (!sold) {
    // WALLET: atomic claim in its own tx; a lost claim throws and the caller surfaces
    // it (nothing charged yet). No swallow on this path.
    await claimOrderCoupon({
      couponId: quote.couponId,
      maxRedemptions: quote.couponMaxRedemptions,
      firstTimeOnly: quote.couponFirstTimeOnly,
      userId: user.id,
      ipHash: opts?.ipHash ?? null,
      amountCents: quote.couponDiscountCents,
    });
  } else {
    // CARD: confirm the pre-reserved hold. The reserve already took the global slot and
    // both per-person slots, so nothing new is contended here — this is a bookkeeping
    // flip against money that already settled at the discounted price.
    const confirmed = opts?.couponReservationToken
      ? await confirmCouponReservation(opts.couponReservationToken)
      : null;
    if (!confirmed) {
      // No token, or the hold vanished (released/swept) although the card already paid
      // the discounted leg — unreachable while the hold outlives the payable session.
      // Best-effort: record the redemption with a fresh atomic claim so a reconcile
      // still sees it; if even that loses (P2002 / cap full), KEEP the discounted charge
      // (never overcharge) and log — the same swallow discipline the old paid path used.
      try {
        await claimOrderCoupon({
          couponId: quote.couponId,
          maxRedemptions: quote.couponMaxRedemptions,
          firstTimeOnly: quote.couponFirstTimeOnly,
          userId: user.id,
          ipHash: opts?.ipHash ?? null,
          amountCents: quote.couponDiscountCents,
        });
      } catch (e) {
        console.error(
          `[order] coupon reservation ${opts?.couponReservationToken ?? "(none)"} could not be confirmed for paid order ${user.id}; kept sold price`,
          e,
        );
      }
    }
  }
}

