1	/**
2	 * Checkout-coupon RESERVATION core — the fix for the concurrent-card-checkout cap
3	 * bypass (security finding, MED/HIGH).
4	 *
5	 * This MIRRORS lib/promo-redemption.ts exactly, adapted for CouponRedemption:
6	 *   - reserve BEFORE the card is charged (atomic conditional insert + conditional
7	 *     Coupon.timesRedeemed increment) so a second concurrent checkout can't also
8	 *     pass eligibility and settle a second discounted charge;
9	 *   - confirm at fulfilment (RESERVED -> CONSUMED, guarded, idempotent);
10	 *   - release on `checkout.session.expired` / a failed session-open / the worker
11	 *     sweep, so an ABANDONED checkout never permanently burns a redemption slot.
12	 *
13	 * THE PER-PERSON / GLOBAL CAP (before this): lib/order.ts `orderCouponClaimable`
14	 * checked eligibility with advisory READS before opening Stripe, and `claimOrderCoupon`
15	 * ran the atomic claim only at fulfilment — where, on the card path, a failed claim was
16	 * SWALLOWED so a paid provision wasn't stranded. So N concurrent card checkouts all
17	 * passed the read, all paid the discounted price, only ONE redemption recorded while ALL
18	 * N provisioned, defeating one-per-user/IP + global `maxRedemptions`. A RESERVED hold
19	 * closes that: it occupies the two @@unique slots AND has already incremented the global
20	 * counter, so exactly one of N racing checkouts holds the slot; the losers re-quote at
21	 * FULL price (coupon dropped) so displayed === charged for every one of them.
22	 *
23	 * TWO differences from the promo mirror, both because a coupon carries a GLOBAL cap:
24	 *   1. The reserve/release must move `Coupon.timesRedeemed` (reserve +1, release -1),
25	 *      not just the per-person unique rows — the promo has no such counter.
26	 *   2. The reserve is keyed by an ARBITRARY couponId, not the single fixed promo id.
27	 *
28	 * WHY A TYPED VIEW (`couponRedemptionDelegate`): identical reasoning to
29	 * promo-redemption.ts — the Prisma client in this tree is symlinked from prod and only
30	 * regenerated at deploy time, so its types do not yet know CouponRedemption's new
31	 * `state` / `reservedUntil` / `reservationToken` columns. The stale-client cast is
32	 * contained HERE, behind one delegate, so no `as any` leaks into the money flows.
33	 */
34	
35	import { randomUUID } from "crypto";
36	import { Prisma } from "@prisma/client";
37	import { db } from "./db";
38	
39	/** Redemption row lifecycle. Same two states as PromoRedemption. */
40	export const COUPON_STATE = { RESERVED: "RESERVED", CONSUMED: "CONSUMED" } as const;
41	export type CouponRedemptionState = (typeof COUPON_STATE)[keyof typeof COUPON_STATE];
42	
43	/** Internal signal for a guard failure inside the reserve tx (rolls it back). */
44	class CouponReserveError extends Error {}
45	
46	/** The subset of the CouponRedemption delegate this module uses, hand-typed so call
47	 * sites stay type-checked before the client is regenerated. */
48	type CouponRedemptionWhere = {
49	  id?: string;
50	  couponId?: string;
51	  userId?: string;
52	  ipHash?: string;
53	  state?: string;
54	  reservationToken?: string;
55	  reservedUntil?: { lt: Date };
56	};
57	type CouponRedemptionDelegate = {
58	  create(args: {
59	    data: {
60	      couponId: string;
61	      userId: string;
62	      ipHash: string | null;
63	      amountCents: number;
64	      context?: string;
65	      state?: string;
66	      reservedUntil?: Date | null;
67	      reservationToken?: string | null;
68	    };
69	    select?: { id: true };
70	  }): Promise<{ id: string }>;
71	  findFirst(args: {
72	    where: CouponRedemptionWhere;
73	    select?: { id: true; couponId?: true };
74	  }): Promise<{ id: string; couponId?: string } | null>;
75	  findMany(args: {
76	    where: CouponRedemptionWhere;
77	    select?: { id: true; couponId: true };
78	  }): Promise<{ id: string; couponId: string }[]>;
79	  updateMany(args: {
80	    where: CouponRedemptionWhere;
81	    data: { state?: string; reservedUntil?: Date | null };
82	  }): Promise<{ count: number }>;
83	  deleteMany(args: { where: CouponRedemptionWhere }): Promise<{ count: number }>;
84	};
85	
86	/** Anything that carries a `couponRedemption` delegate — the client or a tx client. */
87	type CouponClient = Prisma.TransactionClient | typeof db;
88	
89	/** The one place the stale-client cast lives. */
90	function couponRedemptionDelegate(client: CouponClient): CouponRedemptionDelegate {
91	  return (client as unknown as { couponRedemption: CouponRedemptionDelegate }).couponRedemption;
92	}
93	
94	/**
95	 * Delete THIS claimant's own dead holds for THIS coupon — RESERVED rows whose
96	 * `reservedUntil` has passed and which were never confirmed (an abandoned/expired card
97	 * checkout) — and return each freed slot to the global counter. This is the guarantee
98	 * that an abandoned checkout can NEVER permanently burn a redemption: the very next
99	 * reserve attempt sweeps its own stale hold (and gives the global slot back) before
100	 * contending, independently of the webhook and the worker sweep.
101	 *
102	 * Strictly guarded — `state: RESERVED` AND `reservedUntil < now` — so a CONSUMED grant
103	 * or a still-live hold is NEVER touched. Runs inside the caller's tx. Decrements
104	 * `Coupon.timesRedeemed` by exactly the number of dead holds reaped, so the global cap
105	 * accounting stays exact.
106	 */
107	async function releaseExpiredCouponReservationsFor(
108	  tx: Prisma.TransactionClient,
109	  couponId: string,
110	  userId: string,
111	  ipHash: string | null,
112	): Promise<void> {
113	  const now = new Date();
114	  const d = couponRedemptionDelegate(tx);
115	  // Reap this claimant's own dead holds (by user, and by IP if present). Sum the freed
116	  // slots and hand them back to the global counter in one guarded update.
117	  let freed = 0;
118	  const byUser = await d.deleteMany({
119	    where: { couponId, state: COUPON_STATE.RESERVED, reservedUntil: { lt: now }, userId },
120	  });
121	  freed += byUser.count;
122	  if (ipHash) {
123	    const byIp = await d.deleteMany({
124	      where: { couponId, state: COUPON_STATE.RESERVED, reservedUntil: { lt: now }, ipHash },
125	    });
126	    freed += byIp.count;
127	  }
128	  if (freed > 0) {
129	    // Never let a self-heal drive the counter below zero (defensive against a manual
130	    // row edit); the conditional keeps the decrement honest.
131	    await tx.coupon.updateMany({
132	      where: { id: couponId, timesRedeemed: { gte: freed } },
133	      data: { timesRedeemed: { decrement: freed } },
134	    });
135	  }
136	}
137	
138	export type CouponReserveResult =
139	  | { reserved: true; token: string }
140	  | { reserved: false; error: string };
141	
142	/**
143	 * THE CARD/STRIPE HOLD. Taken BEFORE the card is charged. In ONE transaction it runs the
144	 * exact guards `claimOrderCoupon` runs — first-time-only, the atomic conditional
145	 * `timesRedeemed` increment (the global cap), and the two @@unique inserts
146	 * (one-per-account + one-per-IP) — but writes a RESERVED row (with a token +
147	 * `reservedUntil`) instead of a CONSUMED grant. Exactly one of N racing checkouts wins
148	 * each slot; the losers get `{ reserved: false }` and the caller re-quotes at FULL price
149	 * with the coupon dropped, so its stamped total, card leg and settlement all agree.
150	 *
151	 * The returned `token` is stamped into the Checkout session's metadata and is what
152	 * `confirmCouponReservation` / `releaseCouponReservation` target.
153	 */
154	export async function reserveOrderCoupon(opts: {
155	  couponId: string;
156	  maxRedemptions: number | null;
157	  firstTimeOnly: boolean;
158	  userId: string;
159	  ipHash: string | null;
160	  amountCents: number;
161	  /** When this hold may be reaped if never confirmed (session lifetime + grace). */
162	  reservedUntil: Date;
163	}): Promise<CouponReserveResult> {
164	  const token = `cpr_${randomUUID()}`;
165	  try {
166	    await db.$transaction(async (tx) => {
167	      // Self-heal first: a dead hold from THIS customer's own abandoned card checkout
168	      // (and its held global slot) must not stand between them and a fresh reserve.
169	      await releaseExpiredCouponReservationsFor(tx, opts.couponId, opts.userId, opts.ipHash);
170	
171	      if (opts.firstTimeOnly) {
172	        const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
173	        if (prior > 0) throw new CouponReserveError("This code is for first-time customers only.");
174	      }
175	      // Atomic conditional increment — the global cap. Holds the slot for the duration
176	      // of the checkout; released back if the checkout is abandoned.
177	      const claim = await tx.coupon.updateMany({
178	        where:
179	          opts.maxRedemptions === null
180	            ? { id: opts.couponId, active: true }
181	            : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
182	        data: { timesRedeemed: { increment: 1 } },
183	      });
184	      if (claim.count !== 1) throw new CouponReserveError("That code has just been fully claimed.");
185	      // Conditional INSERT of the RESERVED hold — contends on (coupon,user)/(coupon,ipHash).
186	      // A P2002 here means this account/IP already holds or redeemed it; it throws and
187	      // rolls back the increment above with it, so the global slot is NOT consumed on a
188	      // per-person collision.
189	      await couponRedemptionDelegate(tx).create({
190	        data: {
191	          couponId: opts.couponId,
192	          userId: opts.userId,
193	          ipHash: opts.ipHash,
194	          amountCents: opts.amountCents,
195	          context: "order",
196	          state: COUPON_STATE.RESERVED,
197	          reservedUntil: opts.reservedUntil,
198	          reservationToken: token,
199	        },
200	        select: { id: true },
201	      });
202	    });
203	    return { reserved: true, token };
204	  } catch (e) {
205	    if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === "P2002") {
206	      return { reserved: false, error: "You’ve already used this code." };
207	    }
208	    if (e instanceof CouponReserveError) return { reserved: false, error: e.message };
209	    throw e;
210	  }
211	}
212	
213	/**
214	 * Confirm a hold at fulfilment: flip its RESERVED row to CONSUMED. The `state: RESERVED`
215	 * guard makes it idempotent (a replayed fulfil, or a race with the sweep, matches zero
216	 * rows) and guarantees we never "confirm" a hold that was already released. The global
217	 * `timesRedeemed` counter is left AS-IS — the reserve already incremented it, and a
218	 * confirmed redemption keeps that slot. Returns the row id, or null when there is no
219	 * live hold to confirm.
220	 *
221	 * Runs on the base client in its own tiny tx (the coupon claim has always settled
222	 * outside the order's charge tx — see lib/order.ts — unlike the promo, which confirms
223	 * inside it). The card has already paid the discounted price, so this is a bookkeeping
224	 * flip, not a charge.
225	 */
226	export async function confirmCouponReservation(token: string): Promise<{ id: string } | null> {
227	  return db.$transaction(async (tx) => {
228	    const d = couponRedemptionDelegate(tx);
229	    const row = await d.findFirst({
230	      where: { reservationToken: token },
231	      select: { id: true },
232	    });
233	    if (!row) return null;
234	    const res = await d.updateMany({
235	      where: { reservationToken: token, state: COUPON_STATE.RESERVED },
236	      data: { state: COUPON_STATE.CONSUMED, reservedUntil: null },
237	    });
238	    // count 0 => already consumed (a replay) or released; nothing to newly grant.
239	    return res.count === 1 ? { id: row.id } : null;
240	  });
241	}
242	
243	/**
244	 * Release a hold (delete the RESERVED row) so an abandoned/expired checkout returns BOTH
245	 * the customer's per-person slot AND the global redemption slot. Guarded to
246	 * `state: RESERVED` so it can NEVER delete a CONSUMED grant — a paid, confirmed
247	 * redemption is never revoked by a late expiry event — and it decrements
248	 * `Coupon.timesRedeemed` by exactly one only when it actually deleted the hold, so a
249	 * double release (expiry webhook racing the worker sweep) never over-decrements.
250	 * Called from the `checkout.session.expired` webhook and on a failed session-open.
251	 */
252	export async function releaseCouponReservation(token: string): Promise<void> {
253	  await db.$transaction(async (tx) => {
254	    const d = couponRedemptionDelegate(tx);
255	    const row = await d.findFirst({
256	      where: { reservationToken: token, state: COUPON_STATE.RESERVED },
257	      select: { id: true, couponId: true },
258	    });
259	    if (!row || !row.couponId) return;
260	    const del = await d.deleteMany({
261	      where: { reservationToken: token, state: COUPON_STATE.RESERVED },
262	    });
263	    if (del.count === 1) {
264	      await tx.coupon.updateMany({
265	        where: { id: row.couponId, timesRedeemed: { gte: 1 } },
266	        data: { timesRedeemed: { decrement: 1 } },
267	      });
268	    }
269	  });
270	}
271	
272	/**
273	 * Backstop sweep: release every RESERVED coupon hold whose `reservedUntil` has passed,
274	 * returning each held global slot to its coupon. Runs on the worker so a dead hold is
275	 * reclaimed even if the `checkout.session.expired` webhook is not configured or was
276	 * missed. Guarded to RESERVED, so a CONSUMED grant is untouchable. Returns how many
277	 * were reaped.
278	 *
279	 * Because holds for DIFFERENT coupons can expire together, we delete each row inside its
280	 * own tiny tx (reusing releaseCouponReservation's exact guarded delete-and-decrement) so
281	 * the per-coupon counter accounting is always consistent, never a bulk delete that would
282	 * lose track of how many slots each coupon must get back.
283	 */
284	export async function sweepExpiredCouponReservations(now = new Date()): Promise<number> {
285	  const dead = await couponRedemptionDelegate(db).findMany({
286	    where: { state: COUPON_STATE.RESERVED, reservedUntil: { lt: now } },
287	    select: { id: true, couponId: true },
288	  });
289	  let reaped = 0;
290	  for (const row of dead) {
291	    // One guarded delete-and-decrement per row, so each coupon's global counter is
292	    // returned in lock-step. Guarded to `state: RESERVED` by id: if the webhook (or a
293	    // concurrent sweep) already released this row, count is 0 and the counter is left
294	    // untouched — no over-decrement.
295	    try {
296	      const done = await db.$transaction(async (tx) => {
