import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { classifyCheckoutSession } from "../lib/stripe.ts";

/**
 * THE CHECKOUT-COUPON MONEY RACE (security finding, MED/HIGH). A checkout coupon is
 * capped one-per-account + one-per-IP (two @@unique on CouponRedemption) AND globally
 * by `Coupon.maxRedemptions` (the `timesRedeemed` counter). Every order flow claimed
 * that redemption ATOMICALLY except the up-front-settlement (card/Stripe) path, which
 * pre-screened eligibility with advisory READS (`orderCouponClaimable`), opened a
 * discounted Checkout, and only claimed at FULFILMENT — where, on the card path, a lost
 * claim was SWALLOWED so a paid provision wasn't stranded. So N card checkouts submitted
 * concurrently, all before any redemption row landed, could each pass the read, each pay
 * the discounted price, and each provision, while only ONE redemption recorded —
 * defeating both the per-person caps and the global maxRedemptions.
 *
 * THE FIX (mirrors the first-month-free promo reservation exactly): RESERVE the coupon
 * at checkout-CREATE time BEFORE Stripe — an atomic `timesRedeemed` increment PLUS a
 * RESERVED CouponRedemption insert that contends on the same two unique constraints —
 * keyed to the session by a token in metadata; CONFIRM it at fulfilment (RESERVED ->
 * CONSUMED, counter untouched); RELEASE it on expiry / a failed open / the worker sweep
 * (delete the hold AND hand the global slot back). A second concurrent create can't also
 * reserve, so it DROPS the coupon and re-quotes at FULL price (displayed === charged).
 *
 * DB-free proofs — the pure classifier plus source tripwires — of the shape of the fix,
 * NOT an end-to-end test of the concurrent claim (which needs a live database).
 */

function code(relative: string): string {
  return readFileSync(new URL(relative, import.meta.url), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
}

function session(metadata: Record<string, string> | null, paid = true) {
  return { metadata, payment_status: (paid ? "paid" : "unpaid") as "paid" | "unpaid" };
}

/* ------------------------------------------------------------------ *
 * The coupon hold token round-trips through the Checkout session
 * ------------------------------------------------------------------ */

test("a coupon card order carries its hold token so fulfilment can CONFIRM it", () => {
  const p = classifyCheckoutSession(
    session({
      nxeonUserId: "u1",
      nxeonOrder: '{"planId":"p1","osTemplateId":"os1","hostname":"web","couponCode":"SAVE"}',
      nxeonCouponReservation: "cpr_abc-123",
    }),
  );
  assert.equal(p.kind, "order");
  assert.equal(p.kind === "order" && p.couponReservationToken, "cpr_abc-123");
});

test("a coupon-free card order carries NO coupon hold token (nothing to confirm)", () => {
  const p = classifyCheckoutSession(
    session({ nxeonUserId: "u1", nxeonOrder: '{"planId":"p1","osTemplateId":"os1","hostname":"web"}' }),
  );
  assert.equal(p.kind, "order");
  // Absent metadata parses to null — never "", which parseId already rejects.
  assert.equal(p.kind === "order" && p.couponReservationToken, null);
});

/* ------------------------------------------------------------------ *
 * The reservation is taken BEFORE the card is charged
 * ------------------------------------------------------------------ */

test("payAndDeploy RESERVES the coupon before opening the Checkout session", () => {
  const actions = code("../lib/actions.ts");
  const reserveAt = actions.indexOf("reserveOrderCoupon(");
  const checkoutAt = actions.indexOf("createOrderCheckout(user, cardCents");
  assert.ok(reserveAt > 0, "the card path reserves the coupon");
  assert.ok(checkoutAt > 0, "the card path opens a Checkout session");
  assert.ok(
    reserveAt < checkoutAt,
    "the reserve must precede the session — a hold taken AFTER the discounted session " +
      "exists would leave a window where a second checkout also collects the discount",
  );
});

test("a lost coupon reservation DROPS the coupon and re-quotes at FULL price", () => {
  const actions = code("../lib/actions.ts");
  assert.match(
    actions,
    /intent = \{ \.\.\.intent, couponCode: undefined \};[\s\S]*?orderQuote\(intent, \{ suppressPromo \}\)[\s\S]*?walletSplit\(/,
    "on a lost hold the coupon is dropped, re-quoted full, and the split recomputed — so " +
      "the stamped total, card leg and settlement all agree (displayed === charged)",
  );
});

test("opening the session is passed the coupon hold token, and a failed open RELEASES it", () => {
  const actions = code("../lib/actions.ts");
  assert.match(
    actions,
    /createOrderCheckout\(user, cardCents, intent, orderPriceOf\(quote\), promoCampaign, promoReservationToken, couponReservationToken\)/,
    "the coupon hold token is stamped onto the session",
  );
  assert.match(
    actions,
    /releaseCouponReservation\(couponReservationToken\)/,
    "a session that never comes into being must not burn the customer's coupon slot",
  );
});

/* ------------------------------------------------------------------ *
 * Fulfilment CONFIRMS the reserved hold — never a fresh contended claim
 * ------------------------------------------------------------------ */

test("the card path confirms the reserved coupon instead of racing a fresh swallowed claim", () => {
  const order = code("../lib/order.ts");
  assert.match(
    order,
    /confirmCouponReservation\(opts\.couponReservationToken\)/,
    "card path confirms the pre-reserved hold",
  );
  // The wallet path still claims atomically and surfaces a lost claim (nothing charged).
  assert.match(order, /if \(!sold\) \{[\s\S]*?await claimOrderCoupon\(/, "wallet path still claims atomically");
});

test("fulfilment forwards the coupon hold token from session metadata into placeOrder", () => {
  const fulfil = code("../lib/fulfil-checkout.ts");
  assert.match(
    fulfil,
    /couponReservationToken: order\.couponReservationToken/,
    "the token read off the session must reach placeOrder so the hold is confirmed",
  );
});

/* ------------------------------------------------------------------ *
 * Release / sweep can NEVER revoke a CONSUMED grant, and always return the
 * global slot so an abandoned checkout doesn't burn the coupon
 * ------------------------------------------------------------------ */

test("release is guarded to RESERVED and returns the global slot (never over-decrements)", () => {
  const cr = code("../lib/coupon-redemption.ts");
  assert.match(
    cr,
    /reservationToken: token, state: COUPON_STATE\.RESERVED/,
    "releaseCouponReservation deletes by token AND state RESERVED — a CONSUMED grant is never revoked",
  );
  assert.match(
    cr,
    /timesRedeemed: \{ decrement: 1 \}/,
    "and it returns the global redemption slot so an abandoned checkout doesn't burn the coupon",
  );
});

test("the sweep only reaps RESERVED holds whose window has lapsed", () => {
  const cr = code("../lib/coupon-redemption.ts");
  assert.match(
    cr,
    /state: COUPON_STATE\.RESERVED, reservedUntil: \{ lt: now \}/,
    "the sweep must only reap RESERVED holds that are past due",
  );
});

test("the expired-checkout webhook releases the coupon hold", () => {
  const hook = code("../app/api/stripe/webhook/route.ts");
  assert.match(hook, /checkout\.session\.expired/, "the webhook handles the expiry event");
  assert.match(hook, /releaseCouponReservation\(couponToken\)/, "and releases the coupon hold the session carried");
});

test("the worker sweeps expired coupon holds as a backstop for a missed webhook", () => {
  const worker = code("../worker/index.ts");
  assert.match(worker, /sweepExpiredCouponReservations\(\)/, "the worker loop reaps dead coupon holds");
});

