 * Finding 3: a 100%-off PERCENT coupon with no month cap is refused at source
 * ------------------------------------------------------------------ */

test("admin coupon creation refuses an uncapped 100%-off PERCENT code", () => {
  const growth = code("../lib/actions-growth.ts");
  assert.match(
